// Blue Current — normal paint flows with the production room current.
const FLOW = 2;
const SIZE = 26;
const FADE = 0;
const SPEED = 50;
const LINKS = 0;
const TERRITORY = 0;
const REBUILD_PHOTO = 1;
const PHOTO_OPACITY = 100;
const PHOTO_BLUR = 0;

function brush(point, stroke, t) {
  const marks = [];
  for (let i = 0; i < FLOW; i += 1) {
    const seed = point.index * 37 + i * 23 + stroke.seed * 71;
    const c = photo(point.x, point.y, PHOTO_BLUR);
    if (!c) continue;
    marks.push({
      x: point.x + (rand(seed) - .5) * 9,
      y: point.y + (rand(seed + 7) - .5) * 9,
      size: SIZE * (.8 + rand(seed + 17) * .55),
      alpha: .26 * PHOTO_OPACITY / 100,
      red: c.red, green: c.green, blue: c.blue,
      shape: "streak",
      angle: point.angle * 180 / Math.PI + (rand(seed + 31) - .5) * 12,
      soft: .75
    });
  }
  return marks;
}

function move(mark, t) {
  const phase = t + mark.seed * TAU;
  return {
    dx: ((t * 18 + mark.seed * 55) % 48) - 24,
    dy: Math.sin(phase) * 2.1,
    size: 1 + Math.sin(phase * .8) * .08,
    alpha: .16 + (Math.sin(phase * 1.2) + 1) * .08
  };
}
